    (2110603, ''1968RC00003'', ''EXCEL BANC 11 TROIS'', ''19680402''),
    (2110604, ''1967RA00004'', ''EXCEL BANC 11 QUATRE'', ''19671201''), (2110605, ''1967RC00005'', ''EXCEL BANC 11 CINQ'', ''19671101'');
INSERT INTO v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC, DCJDC_ID_INSTN, DCJDC_NUM_ORDRE, DCJDC_DATE, DCJDC_DATE_PREVUE, DCJDC_TYPE_DECISION) VALUES
    (2110611, 2110601, 1, ''19680310'', NULL, ''BANC11F''), (2110612, 2110602, 1, NULL, ''19680325'', ''BANC11S''),
    (2110613, 2110605, 1, ''19680110'', NULL, ''BANC11F'');
');
